VALUES (NULL, NULL, 18857, 'Ruiner', 'Ruiner', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6knu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6io.jpg', 'Ruiner is a top-down action shooter created in the spirit of cult cyberpunk anime and game classics. Ruiner is quick and brutal but sophisticated gameplay, original world with mature storyline and unique visual style.', 'https://www.igdb.com/games/ruiner', '["PlayStation 4", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 7.7, 0, 9.86666666666666714e+00, '2026-11-19 20:56:22', '2026-11-19 20:56:22')
