VALUES (NULL, NULL, 111837, 'Cloudpunk', 'Cloudpunk', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2jbz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aragm.jpg', 'A neon-noir story in a rain-drenched cyberpunk metropolis. It’s your first night on the job working for the Cloudpunk delivery service. Two rules: Don’t miss a delivery and don’t ask what’s in the package.', 'https://www.igdb.com/games/cloudpunk', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 7.3, 0, 7.02, '2026-11-19 20:56:22', '2026-11-19 20:56:22')
