VALUES (NULL, NULL, 123925, 'Voidtrain', 'Voidtrain', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaowg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4oxa.jpg', 'Become a crew member of an interdimensional express! Discover a new mysterious world inhabited by amazing creatures, dangers and surprises. Upgrade your train, gather new materials and build better weapons! Available in single player, or in online multiplayer with up to 4 people.', 'https://www.igdb.com/games/voidtrain', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 7.0, 0, 8.05, '2026-11-19 20:56:22', '2026-11-19 20:56:22')
