VALUES (NULL, NULL, 159753, 'Mars First Logistics', 'Mars First Logistics', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3npb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aryea.jpg', 'Mars First Logistics is a physics-based open-world simulation game, where you design, build and control your own mechanical creations to deliver important cargo between colony stations on Mars. Earn credits, unlock new technology, upgrade your vehicle and tame the hostile Martian landscape.', 'https://www.igdb.com/games/mars-first-logistics', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 1.1216000000000001e+01, '2026-11-19 20:56:22', '2026-11-19 20:56:22')
