VALUES (NULL, NULL, 348047, 'Wanderburg', 'Wanderburg', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocyc5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3p69.jpg', 'Drive your Castle on Wheels into battle in this minimalist medieval roguelike of roaming fortresses! Devour entire villages, build your modular arsenal of siege weapons and arcane machinery as you grow with every stronghold you crush.', 'https://www.igdb.com/games/wanderburg', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 6.52, '2026-11-19 20:56:22', '2026-11-19 20:56:22')
