VALUES (NULL, NULL, 90055, 'Carrion', 'Carrion', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2eau.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar76w.jpg', 'Carrion is a reverse horror game in which you assume the role of an amorphous alien being. Use your unique otherworldly abilities to your advantage and hunt down your prey!', 'https://www.igdb.com/games/carrion', '["PlayStation 4", "Linux", "Android", "PC (Microsoft Windows)", "iOS", "PlayStation 5", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 7.5, 0, 6.01500000000000056e+00, '2026-11-19 20:56:22', '2026-11-19 20:56:22')
