VALUES (NULL, NULL, 148241, 'Lies of P', 'Lies of P', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6lxr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar243v.jpg', 'Lies of P is an action role-playing game set in a dark, Belle Époque-inspired city overrun by deadly puppets. Players control Pinocchio, reimagined as a mechanical warrior, navigating a decaying world while making choices that affect the unfolding narrative. The game features challenging melee combat, weapon customization, and a mechanical arm with various abilities.', 'https://www.igdb.com/games/lies-of-p', '["Xbox Series X|S", "PlayStation 4", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Xbox One"]', NULL, 8.5, 0, 6.01500000000000056e+00, '2026-11-19 20:56:22', '2026-11-19 20:56:22')
