VALUES (NULL, NULL, 420600, 'Unharvest', 'Unharvest', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cod0c0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6vfo.jpg', 'Drain the life from everything around you in this reverse-farming incremental game. Infect all that grows and upgrade your plagues as the land slowly dies. How far can the decay reach?', 'https://www.igdb.com/games/unharvest', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 6.01, '2026-11-19 20:56:22', '2026-11-19 20:56:22')
