VALUES (NULL, NULL, 332273, 'Monster Train 2', 'Monster Train 2', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coab4k.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3eqh.jpg', 'It''s time to raise Hell in Heaven! Monster Train returns with all new clans, new enemy factions, new challenges, new modes and more! Defend your Pyre in the classic three-tiered, vertical gameplay that made the original roguelike deckbuilder a hit.', 'https://www.igdb.com/games/monster-train-2', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Nintendo Switch"]', NULL, 8.0, 0, 8.01, '2026-11-19 20:56:22', '2026-11-19 20:56:22')
