VALUES (NULL, NULL, 410369, 'Verho: Curse of Faces', 'Verho: Curse of Faces', 'game', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocix0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc14bmn.jpg', 'Verho is a Dark RPG following the tradition of the King’s Field series. Travel to the land of Yariv, find the source of the Curse of Faces, and fight the dangers of this scourge.', 'https://www.igdb.com/games/verho-curse-of-faces--1', NULL, NULL, NULL, 0, 7.01, '2026-11-19 20:56:22', '2026-11-19 20:56:22')
