VALUES (NULL, NULL, 279643, 'The First Berserker: Khazan', 'The First Berserker: Khazan', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8roc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2o8b.jpg', 'The First Berserker: Khazan is a hardcore action role-playing game. The player will become Khazan, the great general of the Pelos empire, whom overcame death, and sets out to reveal the incidents that led to his downfall and seek vengeance on his enemies.', 'https://www.igdb.com/games/the-first-berserker-khazan', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.3, 0, 9.02, '2026-11-19 20:56:22', '2026-11-19 20:56:22')
