VALUES (NULL, NULL, 204647, 'Synergy', 'Synergy', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9s55.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1ut8.jpg', 'Humans live on a hostile planet. In this survival city-building game, develop your city, face natural disasters, make the right choices. Explore this environment-changing world while keeping your people happy despite extreme weather conditions.', 'https://www.igdb.com/games/synergy--2', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, NULL, 0, 10.045, '2026-11-19 20:56:22', '2026-11-19 20:56:22')
