VALUES (NULL, NULL, 139190, 'Under Domain', 'Under Domain', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2her.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ark6c.jpg', 'Under Domain - Alien Invasion Simulator will surprise you with a Sci-fi turn-based game completely different from others. How about turning yourself into an Alien and planning an invasion to Planet Earth? You can secretly influence human history and build war machines to exterminate human beings.', 'https://www.igdb.com/games/under-domain', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 5.02, '2026-11-19 20:56:22', '2026-11-19 20:56:22')
