VALUES (NULL, NULL, 9543, 'Nine Hours, Nine Persons, Nine Doors', 'Nine Hours, Nine Persons, Nine Doors', 'game', 2009, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4hsz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6ca1.jpg', 'The game is a murder mystery visual novel with a heavy story focus that requires multiple playthroughs to figure out and involves puzzle rooms used to progress through the story with dialogue choices to be made inbetween them.', 'https://www.igdb.com/games/nine-hours-nine-persons-nine-doors', '["Nintendo DS"]', NULL, 8.6, 0, 1.02, '2026-11-19 20:56:22', '2026-11-19 20:56:22')
