VALUES (NULL, NULL, 108251, 'Disneyland Adventures', 'Disneyland Adventures', 'game', 2011, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1vxe.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arzzt.jpg', 'Disneyland Adventures allows fans of all ages to explore Disneyland park, enjoy adventures based on 18 popular attractions, engage in 100 challenging quests, and interact with 35 beloved characters. Disneyland Adventures is your ticket to the magical world of Disneyland right in your living room.', 'https://www.igdb.com/games/disneyland-adventures', '["PC (Microsoft Windows)", "Xbox 360", "Xbox One"]', NULL, 5.9, 0, 3.02333333333333342e+00, '2026-11-19 20:56:22', '2026-11-19 20:56:22')
