VALUES (NULL, NULL, 2267, 'Sonic Colors', 'Sonic Colors', 'game', 2010, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4wdr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4l0s.jpg', 'Sonic Colors, titled Sonic Colours in European and Australian markets, is a platforming game in the Sonic the Hedgehog series, developed by Sonic Team and published by Sega in 2010. The game was released worldwide for the Wii in November 2010. Another version featuring different gameplay was also released on the Nintendo DS at the same time.', 'https://www.igdb.com/games/sonic-colors', '["Wii"]', NULL, 7.2, 0, 2.005, '2026-11-19 20:56:22', '2026-11-19 20:56:22')
