VALUES (NULL, NULL, 13815, 'The Big Deal', 'The Big Deal', 'game', 1986, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coc6pm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar60ei.jpg', 'The Big Deal is a unique 1986 cooking simulation game released for the Commodore 64 (and later ported to the Amiga). Developed in Germany, the game stands out for its stressful, micro-management gameplay that tasking players with automated kitchen logistics rather than direct action control', 'https://www.igdb.com/games/the-big-deal', '["Commodore C64/128/MAX", "Amiga"]', NULL, NULL, 0, 1.01, '2026-11-19 20:56:22', '2026-11-19 20:56:22')
