VALUES (NULL, NULL, 472, 'The Elder Scrolls V: Skyrim', 'The Elder Scrolls V: Skyrim', 'game', 2011, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocs1l.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ksgt1c400zmgamznhh9h.jpg', 'Skyrim reimagines and revolutionizes the open-world fantasy epic, bringing to life a complete virtual world open for you to explore any way you choose. Play any type of character you can imagine, and do whatever you want; the legendary freedom of choice, storytelling, and adventure of The Elder Scrolls is realized like never before.', 'https://www.igdb.com/games/the-elder-scrolls-v-skyrim', '["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, 8.4, 0, 0.0, '2026-11-19 20:56:22', '2026-11-19 20:56:22')
