VALUES (NULL, NULL, 3183, 'Sanctum', 'Sanctum', 'game', 2011, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2hky.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arr6s.jpg', 'An inventive tower defense/ first person shooter hybrid that pits elite soldier Skye against various forms of alien life on a small set of unique maps. Skye must build and upgrade defensive structures while jumping into the fray to help her creations take down the hostile invaders.', 'https://www.igdb.com/games/sanctum', '["PC (Microsoft Windows)", "Mac"]', NULL, 6.5, 0, 1.02, '2026-11-19 20:56:22', '2026-11-19 20:56:22')
