VALUES (NULL, NULL, 283486, 'Atlyss', 'Atlyss', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7nm7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2pno.jpg', 'Enter the world of ATLYSS, a single-player/online RPG where you can fight with or against friends in a surreal world filled with creatures beyond comprehension. Customize and progress your character(s), complete quests, and discover strange locations.', 'https://www.igdb.com/games/atlyss', '["PC (Microsoft Windows)"]', NULL, 7.5, 0, 1.01, '2026-11-19 20:56:22', '2026-11-19 20:56:22')
