VALUES (NULL, NULL, 288327, 'Pokémon Legends: Z-A', 'Pokémon Legends: Z-A', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9wzc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3m7o.jpg', 'A new adventure awaits within Lumiose City, where an urban redevelopment plan is underway to shape the city into a place that belongs to both people and Pokémon. Please look forward to seeing it for yourself.​​', 'https://www.igdb.com/games/pokemon-legends-z-a', '["Nintendo Switch 2", "Nintendo Switch"]', NULL, 7.5, 0, 1.0, '2026-11-19 20:56:22', '2026-11-19 20:56:22')
