VALUES (NULL, NULL, 328621, 'Machine Mind', 'Machine Mind', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9aos.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar39s1.jpg', 'Machine Mind is an action game in a post-apocalyptic setting with elements of survival and RTS. You will fight, craft modules, build your transport, develop and protect your base. You can control other vehicles to automate operations. Discover all the secrets of the destroyed world!', 'https://www.igdb.com/games/machine-mind', '["PC (Microsoft Windows)", "Mac"]', NULL, 6.4, 0, 1.16, '2026-11-19 20:56:22', '2026-11-19 20:56:22')
