VALUES (NULL, NULL, 16611, 'Scrap Mechanic', 'Scrap Mechanic', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocxak.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arlb3.jpg', 'Enter the creative paradise of Scrap Mechanic! Build fantastic machines, go on adventures with your friends and defend against waves of evil Farmbots in this imaginative multiplayer survival sandbox. With Scrap Mechanic’s powerful creation tools you can engineer your own adventures!', 'https://www.igdb.com/games/scrap-mechanic', '["PC (Microsoft Windows)"]', NULL, 7.0, 0, 1.01, '2026-11-19 20:56:22', '2026-11-19 20:56:22')
