INSERT INTO "recommendations" ("tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at")
VALUES (NULL, NULL, 6181, 'The Suffering: Ties That Bind', 'The Suffering: Ties That Bind', 'game', 2005, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4pwh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aru9c.jpg', 'The Suffering: Ties That Bind follows in the footsteps of its predecessor by combining a disturbing horror atmosphere with action/shooter gameplay. Players can switch between third person and first person depending on their preference, and will shoot a lot of hideous demonic manifestations of evil before the game is done. The player is also able to transform into a hideous creature at key times in the game, which allows him to engage in intense melee combat. The game includes a morality system which records the player''s actions during gameplay and changes the story accordingly, and also alters the player''s creature form. Everything from the first The Suffering has been refined and turned up a notch for the sequel.', 'https://www.igdb.com/games/the-suffering-ties-that-bind', '["Xbox", "PC (Microsoft Windows)", "PlayStation 2"]', NULL, 7.0, 0, 1.13, '2026-11-19 20:56:22', '2026-11-19 20:56:22')
