VALUES (NULL, NULL, 6939, 'Clive Barker''s Jericho', 'Clive Barker''s Jericho', 'game', 2007, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1ya0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/do3dytesyuptox0vlsfh.jpg', 'Jericho is a horror-themed FPS from the mind of screen legend Clive Barker. In the game, a Jericho Team must fight through a lost city to destroy the evil at its heart.', 'https://www.igdb.com/games/clive-barker-s-jericho', '["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, 7.0, 0, 1.02, '2026-11-19 20:56:22', '2026-11-19 20:56:22')
