VALUES (NULL, NULL, 5808, 'Darkwatch', 'Darkwatch', 'game', 2005, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4oep.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1lkf.jpg', 'Darkwatch mixes the Western, horror and steampunk genres, telling the story of Jericho Cross, an outlaw gunfighter in the late 19th-century American Frontier who has been turned into a vampire and forcibly recruited by the titular monster-hunting secret organization to fight against supernatural forces.', 'https://www.igdb.com/games/darkwatch', '["Xbox", "PlayStation 2"]', NULL, 6.4, 0, 1.02, '2026-11-19 20:56:22', '2026-11-19 20:56:22')
